import { useEffect, useMemo, useRef, useState } from "react";
import QRCode from "qrcode";
import { AlertTriangle, CheckCircle2, Check, ChevronRight, CircleHelp, Copy, Download, FileText, MessageSquareText, QrCode, Search, UserRoundPen } from "lucide-react";
import PageHeader from "../../../components/layout/PageHeader.jsx";
import Modal from "../../../components/feedback/Modal.jsx";
import AsyncDataSurface from "../../../components/feedback/AsyncDataSurface.jsx";
import EmptyState from "../../../components/feedback/EmptyState.jsx";
import Badge from "../../../components/ui/Badge.jsx";
import AdminSummaryGrid from "../../../components/ui/AdminSummaryGrid.jsx";
import { semanticStatusTone } from "../../../components/ui/semanticStatus.js";
import SelectField from "../../../components/forms/SelectField.jsx";
import MonthPickerField from "../../../components/forms/MonthPickerField.jsx";
import DataTable from "../../../components/tables/DataTable.jsx";
import AdminPagination, { useAdminPagedQuery } from "../../../components/tables/AdminPagination.jsx";
import { crewService } from "../../../services/crewService.js";
import AdminFilterToolbar from "../../../components/layout/AdminFilterToolbar.jsx";
import { CrewAdminOutletField } from "../components/CrewAdminToolbar.jsx";
import { useCrewAdminOutlet } from "../context/CrewAdminOutletContext.jsx";

const serviceCriteria = [
  ["welcome_greeting", "Welcome / Greeting"], ["thank_you_goodbye", "Thank You / Goodbye"], ["grooming", "Grooming"],
  ["work_area_cleanliness", "Work Area Cleanliness"], ["guest_interaction", "Guest Interaction"],
];
const conductCriteria = [["professional_conduct", "Professional Conduct"], ["teamwork", "Teamwork"], ["responsibility", "Responsibility"], ["communication", "Communication"], ["policy_compliance", "Policy Compliance"]];
const performanceComponents = [["attendance", "Attendance"], ["service", "Service"], ["customer", "Customer"], ["knowledge", "Knowledge"], ["conduct", "Conduct"]];
const ratings = [{ value: "meets_standard", label: "Meets Standard" }, { value: "needs_improvement", label: "Needs Improvement" }, { value: "not_observed", label: "Not Observed" }];
const periodValue = () => new Date().toISOString().slice(0, 7) + "-01";
const score = (value, max) => max == null ? "—" : value == null ? `— / ${max}` : `${Math.round(Number(value))} / ${max}`;
const statusLabel = (value) => ({ draft: "Draft", review_required: "Review", finalized: "Finalized" }[value] || value);
const formatDate = (value) => value ? new Date(value).toLocaleDateString("en-MY", { day: "numeric", month: "short", year: "numeric" }) : "—";
const formatDateTime = (value) => value ? new Date(value).toLocaleString("en-MY", { day: "numeric", month: "short", year: "numeric", hour: "numeric", minute: "2-digit" }) : "—";

export default function CrewPerformanceAdminPage({ auth, ui, store, initialTab = "overview" }) {
  const { outlets, outletId, setOutletId } = useCrewAdminOutlet(store?.outlets || []); const [period, setPeriod] = useState(periodValue());
  const [data, setData] = useState({ summary: {}, crew: [], reviews: [], feedback: [] }); const [loading, setLoading] = useState(true);
  const [error, setError] = useState(""); const requestSequence = useRef(0);
  const [filters, setFilters] = useState({ query: "", position: "all", status: "all" });
  const [feedbackFilters, setFeedbackFilters] = useState({ query: "", scope: "all", experience: "all", status: "all", trust: "all" });
  const isFeedback = initialTab === "feedback";
  const feedbackQuerySignature = useMemo(() => JSON.stringify({ outletId, period, feedbackFilters }), [feedbackFilters, outletId, period]);
  const [feedbackListing, feedbackListingActions] = useAdminPagedQuery({ storageKey: "crew-customer-feedback", enabled: Boolean(isFeedback && outletId), querySignature: feedbackQuerySignature, loadPage: ({ page, pageSize }) => crewService.feedbackAdminPage({ outletId, period, filters: feedbackFilters, page, pageSize }) });
  const [detail, setDetail] = useState(null); const [review, setReview] = useState(null); const [scoringInfo, setScoringInfo] = useState(false); const [moderation, setModeration] = useState(null); const [feedbackDetail, setFeedbackDetail] = useState(null); const [attribution, setAttribution] = useState(null); const [feedbackQr, setFeedbackQr] = useState(null); const [trustReview, setTrustReview] = useState(null);
  const canReview = auth.hasPermission("crew_performance.review"); const canFinalize = auth.hasPermission("crew_performance.finalize"); const canModerate = auth.hasPermission("crew_feedback.moderate"); const canCorrectAttribution = auth.hasPermission("crew_feedback.correct_attribution"); const canTrustReview = auth.hasPermission("crew_feedback.trust_review"); const canFollowUpManage = auth.hasPermission("crew_feedback.follow_up.manage");
  async function refresh() { if (isFeedback) return feedbackListingActions.refreshNow(); if (!outletId) return; const sequence = ++requestSequence.current; setLoading(true); setError(""); try { const next = await crewService.performanceAdminData(outletId, period); if (sequence === requestSequence.current) setData(next); } catch (cause) { if (sequence === requestSequence.current) { setError(cause.message || "Performance evidence could not be loaded."); ui.notify({ title: "Unable to load Performance", message: cause.message, tone: "error" }); } } finally { if (sequence === requestSequence.current) setLoading(false); } }
  useEffect(() => { if (!isFeedback) refresh(); }, [isFeedback, outletId, period]);
  async function submitReview(values) { await crewService.submitPerformanceReview(values); setReview(null); await refresh(); ui.notify({ title: "Review submitted", message: "The server recalculated this performance component." }); }
  async function finalize(employeeId) { await crewService.finalizePerformance(employeeId, period); setDetail(null); await refresh(); ui.notify({ title: "Performance finalized", message: "This monthly result is now immutable." }); }
  async function moderate(values) { await crewService.moderateFeedback(values.id, values.exclude, values.reason); setModeration(null); await refresh(); ui.notify({ title: values.exclude ? "Feedback excluded" : "Feedback restored to scoring", message: "The moderation history was retained." }); }
  async function correctAttribution(values) { await crewService.correctFeedbackAttribution(values.id, values.employeeId, values.reason); setAttribution(null); await refresh(); ui.notify({ title: "Crew attribution corrected", message: "The prior attribution and correction reason were retained." }); }
  async function confirmTrust(values) { await crewService.confirmFeedbackTrust(values.id, values.reason); setTrustReview(null); setFeedbackDetail(null); await refresh(); ui.notify({ title: "Feedback confirmed", message: "The trust decision was retained and mutable Performance was refreshed." }); }
  async function updateFollowUp(feedbackId, status) { await crewService.updateFeedbackFollowUp(feedbackId, status); await refresh(); setFeedbackDetail((current) => current ? { ...current, follow_up: { ...current.follow_up, status } } : current); ui.notify({ title: "Follow-up updated", message: "The status transition was retained." }); }
  const positions = useMemo(() => [...new Set((data.crew || []).map((row) => row.employee.position).filter(Boolean))].sort(), [data.crew]);
  const meta = isFeedback ? ["Customer Feedback", "Understand guest sentiment without deleting unfavorable feedback."] : ["Performance Overview", "Explainable monthly performance from Attendance, Reviews, Feedback and Learning evidence."];
  return <div className="crew-performance-page"><PageHeader section="Crew · Performance" title={meta[0]} description={meta[1]} secondaryActions={isFeedback ? <button type="button" className="btn-secondary" disabled={!outletId} onClick={() => setFeedbackQr(outlets.find((outlet) => outlet.id === outletId) || null)}><QrCode size={15} /> Feedback QR</button> : null} />
    <PerformanceToolbar outlets={outlets} outletId={outletId} setOutletId={setOutletId} period={period} setPeriod={setPeriod} filters={filters} setFilters={setFilters} feedbackFilters={feedbackFilters} setFeedbackFilters={setFeedbackFilters} positions={positions} feedbackOnly={isFeedback} />
    <AsyncDataSurface loading={isFeedback ? feedbackListing.loading : loading} error={isFeedback ? feedbackListing.error : error} errorTitle={`Unable to load ${meta[0]}`} hasData={isFeedback ? feedbackListing.rows.length > 0 : data.crew.length > 0} isEmpty={isFeedback ? feedbackListing.hasLoaded && feedbackListing.loadedTotal === 0 : data.crew.length === 0} emptyTitle={isFeedback ? "No Customer Feedback" : "No performance records yet"} emptyDescription={isFeedback ? "Guest submissions for this outlet and period will appear here." : "Performance records will appear after monthly evidence is available."} onRetry={isFeedback ? feedbackListingActions.retry : refresh}>
      {isFeedback ? <FeedbackAdmin data={feedbackListing.rows} summary={feedbackListing.summary} filters={feedbackFilters} onModerate={setModeration} onDetail={setFeedbackDetail} onCorrectAttribution={setAttribution} canModerate={canModerate} canCorrectAttribution={canCorrectAttribution} pagination={<AdminPagination {...feedbackListing} onPageChange={feedbackListingActions.requestPage} onPageSizeChange={feedbackListingActions.requestPageSize} noun="feedback records" />} /> : <PerformanceOverview data={data} filters={filters} onFiltersChange={setFilters} onOpen={setDetail} onReview={setReview} onScoringInfo={() => setScoringInfo(true)} canReview={canReview} />}
    </AsyncDataSurface>
    {detail ? <PerformanceDetail item={detail} canFinalize={canFinalize} onClose={() => setDetail(null)} onFinalize={() => finalize(detail.employee.id)} /> : null}
    {review ? <PerformanceReview item={review} period={period} onClose={() => setReview(null)} onSubmit={submitReview} /> : null}
    {scoringInfo ? <PerformanceScoringDialog framework={data.scoring_framework} onClose={() => setScoringInfo(false)} /> : null}
    {moderation ? <ModerationDialog item={moderation} onClose={() => setModeration(null)} onSubmit={moderate} /> : null}
    {trustReview ? <TrustDialog item={trustReview} onClose={() => setTrustReview(null)} onSubmit={confirmTrust} /> : null}
    {attribution ? <AttributionDialog item={attribution} employees={isFeedback ? feedbackListing.summary?.feedback_crew || [] : data.feedback_crew || []} onClose={() => setAttribution(null)} onSubmit={correctAttribution} /> : null}
    {feedbackDetail ? <FeedbackDetail item={feedbackDetail} onClose={() => setFeedbackDetail(null)} onConfirmTrust={setTrustReview} onModerate={setModeration} onUpdateFollowUp={updateFollowUp} canTrustReview={canTrustReview} canModerate={canModerate} canFollowUpManage={canFollowUpManage} /> : null}
    {feedbackQr ? <FeedbackQrDialog outlet={feedbackQr} onClose={() => setFeedbackQr(null)} /> : null}
  </div>;
}

function PerformanceToolbar({ outletId, period, setPeriod, filters, setFilters, feedbackFilters, setFeedbackFilters, positions, feedbackOnly }) {
  const current = feedbackOnly ? feedbackFilters : filters;
  const setCurrent = feedbackOnly ? setFeedbackFilters : setFilters;
  const activeFilters = feedbackOnly ? [current.query && { key: "query", label: "Search", value: current.query, onRemove: () => setCurrent((value) => ({ ...value, query: "" })) }, current.scope !== "all" && { key: "scope", label: "Type", value: current.scope === "food" ? "Food & Drinks" : current.scope === "outlet" ? "Overall Visit" : "Crew", onRemove: () => setCurrent((value) => ({ ...value, scope: "all", status: "all", trust: "all" })) }, current.experience !== "all" && { key: "experience", label: "Experience", value: current.experience.replaceAll("_", " "), onRemove: () => setCurrent((value) => ({ ...value, experience: "all" })) }, current.status !== "all" && { key: "status", label: "Scoring", value: current.status, onRemove: () => setCurrent((value) => ({ ...value, status: "all" })) }, current.trust !== "all" && { key: "trust", label: "Trust", value: current.trust.replaceAll("_", " "), onRemove: () => setCurrent((value) => ({ ...value, trust: "all" })) }].filter(Boolean) : [current.query && { key: "query", label: "Search", value: current.query, onRemove: () => setCurrent((value) => ({ ...value, query: "" })) }, current.position !== "all" && { key: "position", label: "Position", value: current.position, onRemove: () => setCurrent((value) => ({ ...value, position: "all" })) }, current.status !== "all" && { key: "status", label: "Status", value: current.status.replaceAll("_", " "), onRemove: () => setCurrent((value) => ({ ...value, status: "all" })) }].filter(Boolean);
  const clear = () => setCurrent(feedbackOnly ? { query: "", scope: "all", experience: "all", status: "all", trust: "all" } : { query: "", position: "all", status: "all" });
  return <AdminFilterToolbar ariaLabel={feedbackOnly ? "Customer Feedback filters" : "Performance filters"} outlet={<CrewAdminOutletField />} period={<MonthPickerField label="Period" value={period.slice(0, 7)} onChange={(value) => setPeriod(`${value}-01`)} />} search={<label className="crew-growth-search"><span>{feedbackOnly ? "Search Feedback" : "Search Crew"}</span><div><Search size={15} /><input value={current.query} onChange={(event) => setCurrent((value) => ({ ...value, query: event.target.value }))} placeholder={feedbackOnly ? "Search Crew, comment or tag" : "Name or employee code"} /></div></label>} filters={feedbackOnly ? <><SelectField label="Feedback type" ariaLabel="Feedback type" value={current.scope} onChange={(scope) => setCurrent((value) => ({ ...value, scope, status: scope === "crew" || scope === "all" ? value.status : "all", trust: scope === "crew" || scope === "all" ? value.trust : "all" }))} options={[{ value: "all", label: "All" }, { value: "crew", label: "Crew" }, { value: "food", label: "Food & Drinks" }, { value: "outlet", label: "Overall Visit" }]} /><SelectField label="Experience" ariaLabel="Feedback experience" value={current.experience} onChange={(experience) => setCurrent((value) => ({ ...value, experience }))} options={[{ value: "all", label: "All" }, { value: "great", label: "Great" }, { value: "okay", label: "Okay" }, { value: "needs_improvement", label: "Needs Improvement" }]} />{current.scope === "crew" || current.scope === "all" ? <><SelectField label="Scoring" ariaLabel="Feedback scoring" value={current.status} onChange={(status) => setCurrent((value) => ({ ...value, status }))} options={[{ value: "all", label: "All" }, { value: "included", label: "Included" }, { value: "excluded", label: "Excluded" }]} /><SelectField label="Trust" ariaLabel="Feedback trust" value={current.trust} onChange={(trust) => setCurrent((value) => ({ ...value, trust }))} options={[{ value: "all", label: "All" }, { value: "standard", label: "Standard" }, { value: "review_required", label: "Review Required" }, { value: "confirmed", label: "Confirmed" }]} /></> : null}</> : <><SelectField label="Position" value={current.position} onChange={(position) => setCurrent((value) => ({ ...value, position }))} options={[{ value: "all", label: "All" }, ...positions.map((value) => ({ value, label: value }))]} /><SelectField label="Status" value={current.status} onChange={(status) => setCurrent((value) => ({ ...value, status }))} options={[{ value: "all", label: "All" }, { value: "awaiting", label: "Awaiting Review" }, { value: "reviewed", label: "Reviewed" }, { value: "finalized", label: "Finalized" }]} /></>} activeFilters={activeFilters} onClear={clear} />;
}

function feedbackPublicLink(token) {
  return `${window.location.origin}/feedback/${encodeURIComponent(token)}`;
}

function feedbackQrFilename(outletName) {
  return `feedx-feedback-${String(outletName || "outlet").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")}.png`;
}

export function FeedbackQrDialog({ outlet, onClose }) {
  const canvasRef = useRef(null); const [error, setError] = useState(""); const [copied, setCopied] = useState(false);
  const token = outlet.public_feedback_token; const link = token ? feedbackPublicLink(token) : "";
  useEffect(() => {
    if (!canvasRef.current || !link) return undefined;
    let active = true;
    QRCode.toCanvas(canvasRef.current, link, { width: 256, margin: 1, color: { dark: "#17273f", light: "#ffffff" } }).catch(() => { if (active) setError("The QR code could not be generated."); });
    return () => { active = false; };
  }, [link]);
  async function copyLink() {
    try { await navigator.clipboard.writeText(link); setCopied(true); window.setTimeout(() => setCopied(false), 1800); } catch { setError("Copy the link directly from the field below."); }
  }
  function downloadQr() {
    if (!canvasRef.current) return;
    const anchor = document.createElement("a");
    anchor.href = canvasRef.current.toDataURL("image/png");
    anchor.download = feedbackQrFilename(outlet.name);
    anchor.click();
  }
  return <Modal title="Feedback QR" description="Guests can scan this code to leave feedback for the selected outlet." onClose={onClose} footer={<button className="btn-secondary" type="button" onClick={onClose}>Close</button>}><div className="crew-feedback-qr"><div className="crew-feedback-qr-outlet"><span>Outlet</span><strong>{outlet.name}</strong></div>{token ? <><div className="crew-feedback-qr-canvas"><canvas ref={canvasRef} aria-label={`Feedback QR for ${outlet.name}`} /></div><label>Public feedback link<input className="control" readOnly value={link} aria-label="Public feedback link" /></label><div className="flex flex-wrap gap-2"><button className="btn-secondary" type="button" onClick={copyLink}><Copy size={15} /> {copied ? <><Check size={15} /> Copied</> : "Copy Link"}</button><button className="btn-primary" type="button" onClick={downloadQr}><Download size={15} /> Download QR</button></div></> : <p className="text-sm text-text-secondary">This outlet does not have a public feedback link yet.</p>}{error ? <p className="text-sm font-semibold text-rose-700">{error}</p> : null}</div></Modal>;
}

function reviewDone(row, component) { const value = row.result.components?.[component]; return value?.status === "reviewed" || value?.score != null; }
function rowReviewStatus(row) { return reviewDone(row, "service") && reviewDone(row, "conduct") ? "completed" : "pending"; }
function componentScore(row, key) { return score(row.result[`${key}_score`], row.result.components?.[key]?.max_score); }
function displayedPerformanceScore(result) { return result.status === "finalized" ? result.total_score : result.current_score; }
function matchesPerformanceFilters(row, filters) {
  const haystack = `${row.employee.full_name} ${row.employee.employee_code || ""} ${row.employee.position || ""}`.toLowerCase();
  if (filters.query && !haystack.includes(filters.query.toLowerCase())) return false;
  if (filters.position !== "all" && row.employee.position !== filters.position) return false;
  if (filters.status === "awaiting" && rowReviewStatus(row) !== "pending") return false;
  if (filters.status === "reviewed" && rowReviewStatus(row) !== "completed") return false;
  if (filters.status === "finalized" && row.result.status !== "finalized") return false;
  return true;
}

function PerformanceOverview({ data, filters, onFiltersChange, onOpen, onReview, onScoringInfo, canReview }) {
  const s = data.summary || {}; const rows = data.crew || [];
  const reviewed = Number(s.reviewed ?? rows.filter((row) => rowReviewStatus(row) === "completed").length); const awaiting = Number(s.awaiting_review ?? rows.length - reviewed);
  const filteredRows = rows.filter((row) => matchesPerformanceFilters(row, filters));
  const reviewRows = [...filteredRows].sort((a, b) => Number(rowReviewStatus(a) === "completed") - Number(rowReviewStatus(b) === "completed") || a.employee.full_name.localeCompare(b.employee.full_name));
  const maxScore = (data.scoring_framework || []).reduce((total, item) => total + Number(item.max_score || 0), 0);
  return <div className="crew-performance-overview"><AdminSummaryGrid ariaLabel="Period summary" items={[{ label: "Average Score", value: s.average_score == null ? "—" : `${Math.round(s.average_score)} / ${maxScore || "—"}`, helper: `${rows.length} Crew this period` }, { label: "Reviewed", value: `${reviewed} / ${rows.length}`, helper: "Service and Conduct complete", tone: "success" }, { label: "Awaiting Review", value: awaiting, helper: "Service or Conduct pending", tone: awaiting ? "warning" : "neutral", onClick: () => onFiltersChange((current) => ({ ...current, status: "awaiting" })), title: "Show Crew awaiting review" }]} />
    <PerformanceSection title="Review Queue" description="Complete Service Standards and Conduct reviews before finalization."><ReviewQueue rows={reviewRows} onReview={onReview} canReview={canReview} /></PerformanceSection>
    <PerformanceSection title="Team Performance" description={`${filteredRows.length} of ${rows.length} Crew shown for this period.`} action={<button type="button" className="btn-secondary crew-performance-info" onClick={onScoringInfo}><CircleHelp size={15} /> How scoring works</button>}>{filteredRows.length ? <section className="crew-growth-table is-embedded"><DataTable rows={filteredRows} getRowKey={(row) => row.employee.id} onRowClick={onOpen} tableClassName="min-w-[960px] crew-performance-team-table" columns={[
      { key: "employee", header: "Employee", render: (row) => <NameCell row={row.employee} /> },
      { key: "performance", header: "Performance", align: "right", render: (row) => <strong className="crew-performance-total">{displayedPerformanceScore(row.result) == null ? "—" : Math.round(displayedPerformanceScore(row.result))}</strong> },
      ...performanceComponents.map(([key, label]) => ({ key, header: label, align: "right", render: (row) => <span className="crew-performance-number">{componentScore(row, key)}</span> })),
      { key: "status", header: "Status", render: (row) => <Badge tone={semanticStatusTone(row.result.status)}>{statusLabel(row.result.status)}</Badge> }, { key: "open", header: "", align: "right", render: () => <ChevronRight size={15} /> },
    ]} /></section> : <EmptyState title={rows.length ? "No Crew match these filters" : "No performance records yet"} description={rows.length ? "Clear or adjust the filters to review the full team." : "Performance records will appear after monthly evidence is available."} />}</PerformanceSection>
  </div>;
}

function ReviewQueue({ rows, onReview, canReview }) {
  if (!rows?.length) return <EmptyState title="No reviews match these filters" description="Clear or adjust the filters to see the manager review queue." />;
  return <section className="crew-growth-table is-embedded"><DataTable rows={rows} getRowKey={(row) => row.employee.id} tableClassName="min-w-[850px]" columns={[
    { key: "employee", header: "Employee", render: (row) => <NameCell row={row.employee} /> },
    { key: "service", header: "Service Standards", render: (row) => <ReviewCell row={row} component="service" onReview={onReview} canReview={canReview} /> },
    { key: "conduct", header: "Conduct", render: (row) => <ReviewCell row={row} component="conduct" onReview={onReview} canReview={canReview} /> },
    { key: "status", header: "Overall", render: (row) => <Badge tone={rowReviewStatus(row) === "completed" ? "neutral" : "warning"}>{rowReviewStatus(row) === "completed" ? "Completed" : "Review"}</Badge> },
  ]} /></section>;
}

function ReviewCell({ row, component, onReview, canReview }) { const done = reviewDone(row, component); return <span className="crew-performance-review-cell"><Badge tone={semanticStatusTone(done ? "completed" : "pending")}>{done ? "Completed" : "Pending"}</Badge><button type="button" className={done ? "btn-ghost" : "btn-primary"} disabled={!canReview} onClick={() => onReview({ ...row, component })}>Review</button></span>; }
function PerformanceSection({ title, description, action, children }) { return <section className="crew-performance-section"><header><div><h2>{title}</h2><p>{description}</p></div>{action}</header>{children}</section>; }

function PerformanceScoringDialog({ framework, onClose }) { return <Modal title="How scoring works" description="Component weights are supplied by the server with this Performance period." onClose={onClose} footer={<button className="btn-secondary" type="button" onClick={onClose}>Close</button>}><div className="crew-performance-scoring"><dl>{(framework || []).map((item) => <div key={item.key}><dt>{item.label}</dt><dd>{item.max_score} pts</dd></div>)}</dl><p>Attendance, Customer and Knowledge use protected evidence. Service Standards and Conduct use manager reviews. Finalized results remain immutable.</p></div></Modal>; }

function FeedbackAdmin({ data, summary, onModerate, onDetail, onCorrectAttribution, canModerate, canCorrectAttribution, pagination }) {
  const rows = data || [];
  const totals = summary || {}; const total = Number(totals.total_feedback || 0); const positive = Number(totals.positive_feedback || 0);
  return <div className="crew-growth-stack"><AdminSummaryGrid ariaLabel="Customer Feedback summary" items={[{ label: "Total Feedback", value: total, helper: "All guest submissions this period", icon: MessageSquareText }, { label: "Great Experience", value: total ? `${Math.round(positive * 100 / total)}%` : "—", helper: "Across all feedback types", tone: "success", icon: CheckCircle2 }, { label: "Needs Improvement", value: Number(totals.needs_improvement_feedback || 0), helper: "Across all feedback types", tone: "warning", icon: AlertTriangle }, { label: "Trust Review", value: Number(totals.review_required_feedback || 0), helper: "Evidence retained until confirmed or excluded", tone: Number(totals.review_required_feedback || 0) ? "warning" : "neutral", icon: FileText }]} /><section className="crew-growth-table">{rows.length ? <DataTable rows={rows} getRowKey={(row) => row.id} tableClassName="min-w-[1120px]" columns={[
    { key: "date", header: "Date", render: (row) => formatDate(row.submitted_at) }, { key: "type", header: "Type", render: (row) => <Badge tone={row.scope === "crew" ? "info" : "neutral"}>{row.scope === "food" ? "Food & Drinks" : row.scope === "outlet" ? "Overall Visit" : "Crew"}</Badge> }, { key: "crew", header: "Crew", render: (row) => row.scope === "crew" ? <span><strong>{row.employee_name}</strong>{row.employee_position ? <small className="block text-text-secondary">{row.employee_position}</small> : null}</span> : "—" }, { key: "experience", header: "Experience", render: (row) => <Badge tone={row.experience === "great" ? "success" : row.experience === "needs_improvement" ? "warning" : "neutral"}>{row.experience.replaceAll("_", " ")}</Badge> },
    { key: "tags", header: "Tags", render: (row) => <FeedbackTags row={row} compact /> }, { key: "comment", header: "Comment", render: (row) => <span className="block max-w-56 truncate">{row.comment || "—"}</span> }, { key: "trust", header: "Trust", render: (row) => row.scope === "crew" ? <Badge tone={semanticStatusTone(row.trust_state)}>{row.trust_state === "review_required" ? "Review Required" : row.trust_state || "Standard"}</Badge> : <span className="text-text-secondary">—</span> }, { key: "scoring", header: "Scoring", render: (row) => row.scope === "crew" ? <span><Badge tone={semanticStatusTone(row.scoring_status)}>{row.scoring_status}</Badge>{row.scoring_status === "excluded" ? <small className="mt-1 block max-w-40 truncate text-text-secondary" title={row.exclusion_reason || ""}>{row.exclusion_reason || "Reason retained"}</small> : null}</span> : <span className="text-text-secondary">Not applicable</span> },
    { key: "action", header: "Action", align: "right", render: (row) => <span className="flex justify-end gap-2"><button type="button" className="icon-btn" aria-label={`View feedback details for ${row.employee_name || row.scope}`} title="Feedback details" onClick={() => onDetail(row)}><FileText size={15} /></button>{row.scope === "crew" && canCorrectAttribution ? <button type="button" className="icon-btn" aria-label={`Correct Crew attribution for ${row.employee_name}`} title="Correct Crew attribution" onClick={() => onCorrectAttribution(row)}><UserRoundPen size={15} /></button> : null}{row.scope === "crew" && canModerate ? <button type="button" className="btn-secondary" onClick={() => onModerate({ ...row, exclude: row.scoring_status === "included" })}>{row.scoring_status === "included" ? "Exclude" : "Restore"}</button> : null}</span> },
  ]} /> : <EmptyState title="No feedback matches these filters" description="Clear or adjust the Customer Feedback filters to see retained evidence." />}{pagination}</section></div>;
}

function FeedbackTags({ row, compact = false }) {
  const positive = row.positive_tags || []; const improvement = row.improvement_tags || [];
  if (!positive.length && !improvement.length) return "—";
  return <div className={compact ? "space-y-1 text-xs" : "space-y-2"}>{positive.length ? <div><small className="mr-1 text-text-secondary">Positive</small>{positive.map((tag) => <Badge key={tag} tone="success">{tag}</Badge>)}</div> : null}{improvement.length ? <div><small className="mr-1 text-text-secondary">Improve</small>{improvement.map((tag) => <Badge key={tag} tone="warning">{tag}</Badge>)}</div> : null}</div>;
}

function PerformanceDetail({ item, canFinalize, onClose, onFinalize }) {
  const r = item.result;
  const current = displayedPerformanceScore(r); const finalized = r.status === "finalized";
  return <Modal title={`${item.employee.full_name} · Performance`} description={`${new Date(r.period_start).toLocaleDateString("en-MY", { month: "long", year: "numeric" })} · ${statusLabel(r.status)}`} size="xl" onClose={onClose} footer={<><button className="btn-secondary" onClick={onClose}>Close</button>{canFinalize && !finalized ? <button className="btn-primary" disabled={r.service_score == null || r.conduct_score == null} onClick={onFinalize}>Finalize Performance</button> : null}</>}><div className="crew-performance-detail"><section className="crew-performance-score"><span>{finalized ? "Overall Score" : "Current Score"}</span><strong>{current == null ? "—" : Math.round(current)}</strong><small>{finalized ? r.calculation_version : r.status === "draft" ? "Current score · Ready to finalize" : "Current score · Review in progress"}</small></section><div className="crew-performance-breakdown">{performanceComponents.map(([key, label]) => { const value = r.components?.[key]; const max = value?.max_score; return <article key={key}><header><strong>{label}</strong><span>{score(value?.score, max)}</span></header><div className="crew-performance-bar"><i style={{ width: `${value?.score == null || !max ? 0 : Number(value.score) * 100 / max}%` }} /></div><p>{value?.explanation || (value?.status === "review_required" ? "Manager review required." : "Evidence is being calculated.")}</p></article>; })}</div></div></Modal>;
}

function PerformanceReview({ item, period, onClose, onSubmit }) {
  const definitions = item.component === "service" ? serviceCriteria : conductCriteria; const existing = item.result.components?.[item.component]?.criteria || [];
  const [criteria, setCriteria] = useState(() => definitions.map(([key, label]) => ({ key, label, rating: existing.find((row) => row.key === key)?.rating || "not_observed" }))); const [note, setNote] = useState(""); const [saving, setSaving] = useState(false);
  async function submit() { setSaving(true); try { await onSubmit({ employeeId: item.employee.id, period, component: item.component, criteria, note }); } finally { setSaving(false); } }
  return <Modal title={item.component === "service" ? "Service Standards Review" : "Conduct Review"} description={`${item.employee.full_name} · ${new Date(period).toLocaleDateString("en-MY", { month: "long", year: "numeric" })}`} size="xl" onClose={onClose} footer={<><button className="btn-secondary" onClick={onClose}>Cancel</button><button className="btn-primary" disabled={saving || criteria.every((row) => row.rating === "not_observed")} onClick={submit}>{saving ? "Submitting…" : "Submit Review"}</button></>}><div className="crew-performance-review">{criteria.map((row, index) => <article key={row.key}><strong>{row.label}</strong><div role="group" aria-label={`${row.label} rating`}>{ratings.map((rating) => <button type="button" key={rating.value} className={row.rating === rating.value ? "is-active" : ""} aria-pressed={row.rating === rating.value} onClick={() => setCriteria((current) => current.map((entry, i) => i === index ? { ...entry, rating: rating.value } : entry))}>{rating.label}</button>)}</div></article>)}<label>Manager note<textarea className="control" maxLength={1000} value={note} onChange={(event) => setNote(event.target.value)} placeholder="Optional coaching context. This is never shown to Crew." /></label></div></Modal>;
}

function ModerationDialog({ item, onClose, onSubmit }) { const [reason, setReason] = useState(""); const exclude = item.exclude !== false; return <Modal title={exclude ? "Exclude From Scoring" : "Restore To Scoring"} description={exclude ? "The feedback remains visible and the reason is audited." : "This returns the existing feedback to Performance scoring and records the reason."} onClose={onClose} footer={<><button className="btn-secondary" onClick={onClose}>Cancel</button><button className={exclude ? "btn-danger" : "btn-primary"} disabled={reason.trim().length < 5} onClick={() => onSubmit({ id: item.id, exclude, reason })}>{exclude ? "Exclude" : "Restore To Scoring"}</button></>}><label className="crew-performance-moderation">Reason<textarea className="control" value={reason} onChange={(event) => setReason(event.target.value)} placeholder={exclude ? "Explain why this submission should not affect scoring" : "Explain why this feedback should return to scoring"} /></label></Modal>; }

function TrustDialog({ item, onClose, onSubmit }) { const [reason, setReason] = useState(""); return <Modal title="Confirm As Valid" description="This preserves the original evidence and permits included Crew feedback to contribute to mutable Performance. The decision is audited." onClose={onClose} footer={<><button className="btn-secondary" onClick={onClose}>Cancel</button><button className="btn-primary" disabled={reason.trim().length < 5} onClick={() => onSubmit({ id: item.id, reason })}>Confirm As Valid</button></>}><label className="crew-performance-moderation">Reason<textarea className="control" value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Explain why this feedback is valid for scoring" /></label></Modal>; }

function AttributionDialog({ item, employees, onClose, onSubmit }) {
  const [query, setQuery] = useState(""); const [employeeId, setEmployeeId] = useState(item.employee_id); const [reason, setReason] = useState("");
  const choices = employees.filter((employee) => `${employee.name} ${employee.position || ""}`.toLowerCase().includes(query.toLowerCase()));
  return <Modal title="Correct Crew Attribution" description={`Currently attributed to ${item.employee_name}. The original feedback stays unchanged and this correction is audited.`} size="lg" onClose={onClose} footer={<><button className="btn-secondary" onClick={onClose}>Cancel</button><button className="btn-primary" disabled={employeeId === item.employee_id || reason.trim().length < 5} onClick={() => onSubmit({ id: item.id, employeeId, reason })}>Save Correction</button></>}><div className="space-y-4"><label>Find Crew<input className="control mt-1 w-full" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search Crew name or position" /></label><fieldset><legend className="field-label mb-2">Replacement Crew</legend><div className="max-h-56 space-y-2 overflow-y-auto">{choices.map((employee) => <label key={employee.id} className="flex cursor-pointer items-center gap-3 rounded-lg border border-border bg-white p-3 text-sm"><input type="radio" name="feedback-attribution" checked={employeeId === employee.id} onChange={() => setEmployeeId(employee.id)} /><span><strong className="block">{employee.name}</strong><small className="text-text-secondary">{[employee.position, employee.availability === "historical" ? "Historical outlet evidence" : "Active Crew"].filter(Boolean).join(" · ")}</small></span></label>)}{choices.length === 0 ? <p className="text-sm text-text-secondary">No Crew match this search.</p> : null}</div></fieldset><label>Correction reason<textarea className="control mt-1 min-h-24 w-full" value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Explain why this feedback belongs to a different Crew member" /></label></div></Modal>;
}

function LegacyFeedbackDetail({ item, onClose, onConfirmTrust, onModerate, onUpdateFollowUp, canTrustReview, canModerate, canFollowUpManage }) {
  const moderation = item.moderation_history || []; const attribution = item.attribution_history || []; const trust = item.trust_history || []; const followUp = item.follow_up;
  const crewEvidence = item.scope === "crew";
  return <Modal title="Feedback Detail" description={crewEvidence ? "Original guest evidence is retained separately from scoring decisions." : "This guest evidence is retained for outlet improvement and never affects Crew Performance."} size="xl" onClose={onClose} footer={<><button className="btn-secondary" onClick={onClose}>Close</button>{crewEvidence && item.trust_state === "review_required" && canTrustReview ? <button className="btn-primary" onClick={() => onConfirmTrust(item)}>Confirm As Valid</button> : null}{crewEvidence && item.scoring_status === "included" && canModerate ? <button className="btn-danger" onClick={() => onModerate({ ...item, exclude: true })}>Exclude From Scoring</button> : null}</>}><div className="space-y-5 text-sm"><dl className="grid gap-4 sm:grid-cols-2"><DetailItem label="Submitted" value={formatDateTime(item.submitted_at)} /><DetailItem label="Visit time" value={item.visit_at ? formatDateTime(item.visit_at) : "Not required"} /><DetailItem label="Type" value={item.scope === "food" ? "Food & Drinks" : item.scope === "outlet" ? "Overall Visit" : "Crew"} /><DetailItem label="Crew" value={crewEvidence ? item.employee_name : "Not applicable"} /><DetailItem label="Experience" value={item.experience.replaceAll("_", " ")} />{crewEvidence ? <><DetailItem label="Trust" value={<Badge tone={item.trust_state === "confirmed" ? "success" : item.trust_state === "review_required" ? "warning" : "neutral"}>{item.trust_state === "review_required" ? "Review Required" : item.trust_state || "Standard"}</Badge>} /><DetailItem label="Scoring" value={<Badge tone={item.scoring_status === "included" ? "info" : "neutral"}>{item.scoring_status}</Badge>} /></> : null}</dl><section><h3 className="mb-2 font-semibold">Tags</h3><FeedbackTags row={item} /></section><section><h3 className="mb-2 font-semibold">Comment</h3><p className="whitespace-pre-wrap rounded-lg border border-border bg-surface px-3 py-2 text-text-secondary">{item.comment || "No comment provided."}</p></section>{crewEvidence && item.trust_state === "review_required" ? <section><h3 className="mb-2 font-semibold">Trust review</h3><p className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-amber-900">{(item.trust_reason_codes || []).map((reason) => ({ same_device_crew_business_day: "Same device and Crew on this business day", rapid_submissions: "Rapid repeated submissions", repeat_positive_pattern: "Repeated positive pattern", crew_account_match: "Crew account matched the selected Crew", similar_repeat: "Near-identical repeat" })[reason] || reason).join(" · ") || "Server review required."}</p></section> : null}{crewEvidence && item.scoring_status === "excluded" ? <section><h3 className="mb-2 font-semibold">Current Exclusion</h3><dl className="grid gap-3 rounded-lg border border-border bg-surface p-3 sm:grid-cols-3"><DetailItem label="Reason" value={item.exclusion_reason || "—"} /><DetailItem label="Excluded by" value={item.excluded_by_name || "—"} /><DetailItem label="Excluded at" value={formatDateTime(item.excluded_at)} /></dl></section> : null}{item.follow_up_requested ? <section><h3 className="mb-2 font-semibold">Guest follow-up</h3>{followUp ? <div className="rounded-lg border border-border bg-surface p-3"><dl className="grid gap-3 sm:grid-cols-2"><DetailItem label="Preferred name" value={followUp.preferred_name} /><DetailItem label="Contact" value={`${followUp.contact_method}: ${followUp.contact_value}`} /><DetailItem label="Status" value={<Badge tone={followUp.status === "resolved" ? "success" : followUp.status === "in_progress" ? "warning" : "neutral"}>{followUp.status.replaceAll("_", " ")}</Badge>} /></dl>{canFollowUpManage ? <div className="mt-3 flex flex-wrap gap-2">{["requested", "in_progress", "resolved"].filter((status) => status !== followUp.status).map((status) => <button key={status} type="button" className="btn-secondary" onClick={() => onUpdateFollowUp(item.id, status)}>Mark {status.replaceAll("_", " ")}</button>)}</div> : null}</div> : <p className="text-text-secondary">Follow-up contact details are restricted.</p>}</section> : null}{crewEvidence ? <><EvidenceHistory title="Trust decisions" empty="No trust decision has been recorded." entries={trust} render={(entry) => <><strong>{entry.previous_trust_state || "standard"} to {entry.next_trust_state}</strong><span>{entry.reason || (entry.reason_codes || []).join(", ")}</span><small>{entry.decision_source === "system" ? "System" : entry.changed_by || "Admin"} · {formatDateTime(entry.changed_at)}</small></>} /><EvidenceHistory title="Scoring moderation" empty="No scoring moderation has been recorded." entries={moderation} render={(entry) => <><strong>{entry.previous_status} to {entry.next_status}</strong><span>{entry.reason}</span><small>{entry.changed_by || "Admin"} · {formatDateTime(entry.changed_at)}</small></>} /><EvidenceHistory title="Attribution corrections" empty="No attribution correction has been recorded." entries={attribution} render={(entry) => <><strong>{entry.previous_employee_name} to {entry.next_employee_name}</strong><span>{entry.reason}</span><small>{entry.changed_by || "Admin"} · {formatDateTime(entry.changed_at)}</small></>} /></> : null}</div></Modal>;
}

function FeedbackDetail({ item, onClose, onConfirmTrust, onModerate, onUpdateFollowUp, canTrustReview, canModerate, canFollowUpManage }) {
  const crewEvidence = item.scope === "crew";
  const followUp = item.follow_up;
  const scopeLabel = item.scope === "food" ? "Food & Drinks" : item.scope === "outlet" ? "Overall Visit" : "Crew";
  const trustLabel = item.trust_state === "review_required" ? "Review Required" : item.trust_state === "confirmed" ? "Confirmed" : "Standard";
  const trustTone = item.trust_state === "review_required" ? "warning" : item.trust_state === "confirmed" ? "success" : "neutral";
  const tagsPresent = (item.positive_tags || []).length + (item.improvement_tags || []).length > 0;
  const reasonCopy = {
    same_device_crew_business_day: "The same device submitted feedback for this Crew member on the same business day.",
    rapid_submissions: "Several feedback submissions arrived unusually quickly.",
    repeat_positive_pattern: "Repeated positive feedback followed a similar pattern.",
    crew_account_match: "The submission appears connected to the selected Crew member.",
    similar_repeat: "This feedback closely resembles another recent submission.",
  };
  const reviewReason = (item.trust_reason_codes || []).map((reason) => reasonCopy[reason]).filter(Boolean).join(" ") || "This submission needs an Admin trust decision before it can affect Performance.";
  const effectiveScoring = !crewEvidence ? "Does not affect Crew Performance" : item.scoring_status === "excluded" ? "Excluded from Performance" : item.trust_state === "review_required" ? "Pending trust review · Not currently contributing to Performance" : "Contributing to mutable Performance";
  const footerActions = crewEvidence && ((item.trust_state === "review_required" && canTrustReview) || (item.scoring_status === "included" && canModerate));
  const activity = [
    ...(item.trust_history || []).map((entry) => ({ id: `trust-${entry.id}`, at: entry.changed_at, title: entry.next_trust_state === "confirmed" ? "Confirmed as valid" : entry.next_trust_state === "review_required" ? "Trust review required" : "Trust decision updated", detail: entry.reason || (entry.reason_codes || []).map((reason) => reasonCopy[reason]).filter(Boolean).join(" "), actor: entry.decision_source === "system" ? "System" : entry.changed_by || "Admin" })),
    ...(item.moderation_history || []).map((entry) => ({ id: `moderation-${entry.id}`, at: entry.changed_at, title: entry.next_status === "excluded" ? "Excluded from Performance" : "Returned to Performance", detail: entry.reason, actor: entry.changed_by || "Admin" })),
    ...(item.attribution_history || []).map((entry) => ({ id: `attribution-${entry.id}`, at: entry.changed_at, title: "Crew attribution corrected", detail: `${entry.previous_employee_name || "Previous Crew"} reassigned to ${entry.next_employee_name || "Crew member"}.${entry.reason ? ` ${entry.reason}` : ""}`, actor: entry.changed_by || "Admin" })),
    ...((followUp?.history || []).map((entry) => ({ id: `follow-up-${entry.id}`, at: entry.changed_at, title: `Follow-up marked ${entry.next_status?.replaceAll("_", " ") || "updated"}`, detail: null, actor: entry.changed_by || "Admin" }))),
  ].sort((a, b) => new Date(b.at || 0) - new Date(a.at || 0));

  return <Modal title="Feedback Detail" description="Guest evidence and its current operational decision." size="lg" onClose={onClose} bodyClassName="p-0" footer={footerActions ? <><button className="btn-secondary" onClick={onClose}>Close</button>{crewEvidence && item.scoring_status === "included" && canModerate ? <button className="btn-danger" onClick={() => onModerate({ ...item, exclude: true })}>Exclude From Scoring</button> : null}{crewEvidence && item.trust_state === "review_required" && canTrustReview ? <button className="btn-primary" onClick={() => onConfirmTrust(item)}>Confirm As Valid</button> : null}</> : null}>
    <div className="max-h-[calc(85vh-8rem)] space-y-6 overflow-y-auto p-4 text-sm">
      <section aria-labelledby="feedback-evidence-heading">
        <div className="mb-3 flex flex-wrap items-center gap-2"><h3 id="feedback-evidence-heading" className="font-semibold text-text-primary">Feedback Evidence</h3><Badge tone={item.experience === "great" ? "success" : item.experience === "needs_improvement" ? "warning" : "neutral"}>{item.experience.replaceAll("_", " ")}</Badge><Badge tone={crewEvidence ? "info" : "neutral"}>{scopeLabel}</Badge></div>
        <div className="flex flex-wrap gap-x-5 gap-y-3 rounded-lg bg-surface px-3 py-3"><DetailItem label="Crew" value={crewEvidence ? item.employee_name || "Unmatched Crew" : "Not applicable"} /><DetailItem label="Visit time" value={item.visit_at ? formatDateTime(item.visit_at) : "Not required"} /><DetailItem label="Submitted" value={formatDateTime(item.submitted_at)} />{crewEvidence ? <><DetailItem label="Trust" value={<Badge tone={trustTone}>{trustLabel}</Badge>} /><DetailItem label="Performance" value={effectiveScoring} /></> : <DetailItem label="Performance" value={effectiveScoring} />}</div>
        <div className="mt-4"><p className="mb-2 text-xs font-medium uppercase text-text-secondary">Guest comment</p><p className="min-h-16 whitespace-pre-wrap rounded-lg bg-emerald-50 px-4 py-3 text-base leading-6 text-text-primary">{item.comment || "No comment provided."}</p></div>
        {tagsPresent ? <div className="mt-4"><p className="mb-2 text-xs font-medium uppercase text-text-secondary">Tags</p><FeedbackTags row={item} /></div> : null}
        {item.follow_up_requested ? <div className="mt-4 rounded-lg border border-emerald-200 bg-emerald-50 p-3"><div className="mb-2 flex items-center justify-between gap-3"><h4 className="font-semibold">Follow-up</h4>{followUp ? <Badge tone={followUp.status === "resolved" ? "success" : followUp.status === "in_progress" ? "warning" : "neutral"}>{followUp.status.replaceAll("_", " ")}</Badge> : null}</div>{followUp ? <><dl className="grid gap-3 sm:grid-cols-2"><DetailItem label="Preferred name" value={followUp.preferred_name || "—"} /><DetailItem label={followUp.contact_method === "phone" ? "Mobile number" : "Contact"} value={followUp.contact_value || "—"} /><DetailItem label="Follow-up status" value={followUp.status.replaceAll("_", " ")} /></dl>{canFollowUpManage ? <div className="mt-3 flex flex-wrap gap-2">{["requested", "in_progress", "resolved"].filter((status) => status !== followUp.status).map((status) => <button key={status} type="button" className="btn-secondary" onClick={() => onUpdateFollowUp(item.id, status)}>Mark {status.replaceAll("_", " ")}</button>)}</div> : null}</> : <p className="text-text-secondary">Follow-up was requested. Contact details are restricted for your role.</p>}</div> : null}
      </section>

      <section aria-labelledby="trust-decision-heading" className="border-t border-border pt-5"><h3 id="trust-decision-heading" className="mb-3 font-semibold text-text-primary">Trust / Scoring Decision</h3>{crewEvidence && item.trust_state === "review_required" ? <div className="rounded-lg border border-amber-200 bg-amber-50 p-3 text-amber-950"><div className="flex items-center gap-2 font-semibold"><AlertTriangle size={16} />Review required</div><p className="mt-1 leading-5">{reviewReason}</p><p className="mt-2 text-xs font-medium">Pending trust review · Not currently contributing to Performance</p></div> : <div className="rounded-lg bg-surface p-3"><p className="font-medium text-text-primary">{effectiveScoring}</p>{item.scoring_status === "excluded" && item.exclusion_reason ? <p className="mt-1 text-text-secondary">{item.exclusion_reason}</p> : null}</div>}</section>

      <section aria-labelledby="activity-heading" className="border-t border-border pt-5"><h3 id="activity-heading" className="mb-3 font-semibold text-text-primary">Activity</h3>{activity.length ? <ol className="space-y-3">{activity.map((entry) => <li key={entry.id} className="border-l-2 border-emerald-200 pl-3"><p className="font-medium text-text-primary">{entry.title}</p>{entry.detail ? <p className="mt-0.5 text-text-secondary">{entry.detail}</p> : null}<p className="mt-1 text-xs text-text-secondary">{entry.actor} · {formatDateTime(entry.at)}</p></li>)}</ol> : <p className="rounded-lg bg-surface px-3 py-2 text-text-secondary">No recorded decisions or corrections yet.</p>}</section>
    </div>
  </Modal>;
}

function DetailItem({ label, value }) { return <div><dt className="text-xs text-text-secondary">{label}</dt><dd className="mt-1 font-medium">{value}</dd></div>; }
function EvidenceHistory({ title, empty, entries, render }) { return <section><h3 className="mb-2 font-semibold">{title}</h3>{entries.length ? <div className="space-y-2">{entries.map((entry) => <article key={entry.id} className="grid gap-1 rounded-lg border border-border bg-surface p-3">{render(entry)}</article>)}</div> : <p className="text-text-secondary">{empty}</p>}</section>; }
function NameCell({ row }) { return <span className="crew-growth-name"><span className="crew-growth-avatar">{row.full_name.split(/\s+/).slice(0, 2).map((part) => part[0]).join("")}</span><span><strong>{row.full_name}</strong><small>{[row.position, row.employee_code].filter(Boolean).join(" · ") || "Crew"}</small></span></span>; }
